// Fresh saved B2 links (add_b2_cache.py): skip the B2 calls.
const saved = $getWorkflowStaticData('global').b2;
const b2Fresh = !!(saved && Date.now() - saved.at < 20 * 3600e3 && ["Logo Link", "Assets Link", "Team Link"].every(n => saved.links && saved.links[n]));
return [{ json: { basicAuth: 'Basic ' + Buffer.from(`${$env.B2_KEY_ID}:${$env.B2_APPLICATION_KEY}`).toString('base64'), b2Fresh } }];

const __b2 = $('B2 Ready').first().json; // B2 links, saved or fresh (add_b2_cache.py)
const __$ = n => n === 'Authorize B2' || __b2.links[n] ? (j => ({ isExecuted: true, first: () => ({ json: j }), all: () => [{ json: j }] }))(n === 'Authorize B2' ? __b2.acct : __b2.links[n]) : $(n);

const rows = __$('Load Tournaments').all().map(i => i.json).filter(r => r && r._set);
const b2 = __$('Authorize B2').isExecuted ? __$('Authorize B2').first().json : {};
const tokenOf = node => { try { return __$(node).isExecuted ? __$(node).first().json.authorizationToken : null; } catch { return null; } };
const dl = b2?.apiInfo?.storageApi?.downloadUrl;
const signed = key => {
  const t = key && tokenOf(key.startsWith('tournament_assets/') ? 'Assets Link' : key.startsWith('team_assets/') ? 'Team Link' : 'Logo Link');
  return key && dl && t ? `${dl}/file/mypaltan-profile-photos/${key.split('/').map(encodeURIComponent).join('/')}?Authorization=${t}` : null;
};
const parseTags = t => { if (Array.isArray(t)) return t; try { return JSON.parse(t || '[]'); } catch { return []; } };
// Every listed tournament (as the app's All tab): live, upcoming, the featured leagues (opening soon), then completed.
const parseJ = v => { if (v == null) return null; if (typeof v === 'object') return v; try { return JSON.parse(v); } catch { return null; } };
const tournaments = rows.filter(r => r._set === 'tournament').map(r => ({
  slug: r.slug || null, code: r.code || null, name: r.name, sport: r.sport, logo_url: signed(r.logo_key) || r.logo_url || null, start_date: r.start_date || null,
  area: r.area || null, city: r.city, tags: parseTags(r.tags), status: r.status, entry_type: r.entry_type || 'OPEN',
  stage: ['LIVE', 'UPCOMING', 'COMPLETED'][Number(r.stage)] || 'UPCOMING', featured: !r.code,
  champions: Number(r.stage) === 2 ? (parseJ(r.champions) || []).map(x => ({ division: x.division, team: x.team, logo_url: signed(x.logo_key) })) : [],
})).sort((a, b) => ({ LIVE: 0, UPCOMING: 1, COMPLETED: 3 }[a.stage] + (a.featured ? 1 : 0)) - ({ LIVE: 0, UPCOMING: 1, COMPLETED: 3 }[b.stage] + (b.featured ? 1 : 0)));
const banners = rows.filter(r => r._set === 'banner').map(r => ({
  id: r.id, title: r.title, subtitle: r.subtitle || null, badge: r.badge || null, image_url: signed(r.image_key) || r.image_url || null,
  theme: r.theme, cta_label: r.cta_label || null, link_type: r.link_type, link_value: r.link_value || null,
}));
const unreadRow = rows.find(r => r._set === 'unread');

return [{ json: { status: 200, body: { success: true, featured_tournaments: tournaments } } }];

// The B2 links: saved ones while fresh, else the ones just fetched (saved for next time when all succeeded).
const store = $getWorkflowStaticData('global');
if ($('B2 Credentials').first().json.b2Fresh) return [{ json: { acct: store.b2.acct, links: store.b2.links } }];
const a = $('Authorize B2').first().json;
const acct = { apiInfo: a.apiInfo, authorizationToken: a.authorizationToken };
const links = {};
for (const n of ["Logo Link", "Assets Link", "Team Link"]) { try { const t = $(n).first().json.authorizationToken; if (t) links[n] = { authorizationToken: t }; } catch {} }
if (acct.authorizationToken && acct.apiInfo && Object.keys(links).length === 3) store.b2 = { at: Date.now(), acct, links };
return [{ json: { acct, links } }];
